//! Raw FFI bindings to the vendored `libiec61850`
//! (https://github.com/mz-automation/libiec61850), generated by `bindgen` in
//! `build.rs`.
//!
//! 保持为对 C API 的薄、unsafe、1:1 映射; 安全封装放在 `client` 模块。
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
